(function(root){'use strict';const A=root.AIBrain=root.AIBrain||{};A.selectAssets=function(request,assetIndex,opts={}){const tokens=A.tokens(request),limit=opts.limit||20;return(assetIndex?.assets||[]).map(a=>{const hay=A.norm([a.path,a.originalPath,a.category,...(a.tags||[])].join(' '));let score=0;for(const t of tokens)if(hay.includes(t))score++;return{asset:a,score}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.asset.bytes-b.asset.bytes).slice(0,limit).map(x=>x.asset);};})(typeof globalThis!=='undefined'?globalThis:this);
